package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    private final Path file;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
        this.file = Path.of(path);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
import { Pipe, PipeTransform, inject } from '@angular/core';
import { formatNumber, getCurrencySymbol } from '@angular/common';
import { CurrencyService } from './currency.service';

/** Rounds an amount to the nearest multiple of the step (both in whole cents), halves away from zero. */
export function roundToStep(amount: number, step: number): number {
  const stepCents = Math.max(1, Math.round(step * 100));
  const cents = Math.round(Math.abs(amount) * 100);
  return (Math.sign(amount) * Math.round(cents / stepCents) * stepCents) / 100;
}

/**
 * Fits digits info such as '1.2-4' to a currency's decimal places: the minimum fraction digits become the
 * currency's, and the maximum is never fewer than that.
 */
export function digitsFor(digitsInfo: string, decimals: number): string {
  const match = /^(\d+)\.(\d+)-(\d+)$/.exec(digitsInfo);
  if (!match) {
    return digitsInfo;
  }
  return `${match[1]}.${decimals}-${Math.max(decimals, Number(match[3]))}`;
}

/**
 * Shows an amount in a currency: with the currency's symbol and decimal places (none for yen), rounded to
 * the currency's rounding step (e.g. to the nearest five cents) and never finer than its smallest unit.
 * Pass `rounded` false for rates such as unit prices, which are shown as they are. Without explicit digits
 * info an amount is shown with exactly the currency's decimal places. Impure so it picks up the currencies
 * once they load or their rounding changes.
 */
#!/usr/bin/env bash
# Build, start the whole app, run the Playwright specs present in e2e/specs, then stop.
set -euo pipefail
cd "$(dirname "$0")/.."

export PORT="${PORT:-3000}"
export BASE_URL="http://localhost:${PORT}"
# Known audit file, shared by the app (bin/start) and the specs (support/audit.ts). Absolute.
export AUDIT_FILE="${AUDIT_FILE:-$PWD/.run/audit.log}"

bin/build
bin/start
cleanup() { bin/stop || true; }
trap cleanup EXIT

# Wait for readiness (Actuator health), then run the Playwright specs against BASE_URL.
for i in $(seq 1 60); do
  if curl -fsS "${BASE_URL}/actuator/health" >/dev/null 2>&1; then break; fi
  sleep 1
done

# Install deps + the Chromium browser (both cached after first run), then run the specs.
( cd e2e && npm ci --silent && npx --yes playwright install chromium && npx playwright test )

